class DeepSeekError(RuntimeError):
    """DeepSeek 调用失败。message 已脱敏。

    code 是结构化错误码，供调用方决定降级策略：
      "auth"      → 401，Key 无效（换 Key 或切本地）
      "balance"   → 402，余额不足（整轮报废，必须切本地/落盘续跑）
      "rate"      → 429，限流（可稍后重试）
      "timeout"   → 连接/读取超时（切本地或落盘续跑）
      "network"   → 其他网络异常
      "server"    → 5xx
      "http"      → 其他非 200
      "empty"     → 模型没返回内容
      "unknown"   → 兜底
    """

    def __init__(self, message: str, code: str = "unknown", status: int | None = None):
        super().__init__(message)
        self.code = code
        self.status = status


def _code_for_status(status: int) -> str:
    if status == 401:
        return "auth"
    if status == 402:
        return "balance"
    if status == 429:
        return "rate"
    if status >= 500:
        return "server"
    return "http"


def _code_for_exc(e: BaseException) -> str:
    """把 requests 异常归类成结构化错误码（超时单独拎出来）。"""
    if isinstance(e, requests.Timeout):
        return "timeout"
    if isinstance(e, requests.ConnectionError):
        return "network"
    if isinstance(e, requests.RequestException):
        return "network"
    return "unknown"

